using System;
using System.Collections.Generic;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Text.Json;
using System.Text.Json.Serialization;

namespace MitPlan;

// Visible encounter events and sync metadata generated from OverlayPlugin/cactbot
// commit e39b65d4f971a18de41e84b61f82d67d0f555d29. Mitigation plans are not stored here.
internal static class CactbotEncounterTimelines
{
    public const string SourceCommit = "e39b65d4f971a18de41e84b61f82d67d0f555d29";
    private static readonly Lazy<Dictionary<string, List<EncounterTimelineEvent>>> Timelines = new(Decode);

    public static IReadOnlyList<EncounterTimelineEvent> For(string fightId) =>
        Timelines.Value.TryGetValue(fightId, out var events) ? events : [];

    public static float? PhaseStart(string fightId, string phase) => (fightId, phase) switch
    {
        ("m12s", "P1 Lindwurm") => 0,
        ("m12s", "P2 Lindwurm") => 3000,
        ("ucob", "P1 Twintania") => 0,
        ("ucob", "P2 Nael") => 400,
        ("ucob", "P3 Bahamut Prime") => 1000,
        ("ucob", "P4 Adds") => 1488.5f,
        ("ucob", "P5 Golden Bahamut") => 2300,
        ("uwu", "P1 Garuda") => 0,
        ("uwu", "P2 Ifrit") => 300,
        ("uwu", "P3 Titan") => 600,
        ("uwu", "Transition") => 800,
        ("uwu", "P4 Ultima Weapon") => 960,
        ("tea", "P1 Living Liquid") => 0,
        ("tea", "P2 BJCC") => 200,
        ("tea", "P3 Alexander Prime") => 492,
        ("tea", "P4 Perfect Alexander") => 900,
        ("dsr", "P1 Vault Knights") => 0,
        ("dsr", "P2 Thordan") => 550,
        ("dsr", "P3 Nidhogg") => 1000,
        ("dsr", "P4 Eyes") => 1500,
        ("dsr", "Rewind") => 2000,
        ("dsr", "P5 Dark Thordan") => 2996,
        ("dsr", "P6 Double Dragons") => 3500,
        ("dsr", "P7 Dragon King") => 4000,
        ("top", "P1 Omega") => 0,
        ("top", "P2 M/F") => 200,
        ("top", "P3 Reconfigured") => 400,
        ("top", "P4 Blue Screen") => 600,
        ("top", "P5 Delta") => 700,
        ("top", "P5 Sigma") => 819,
        ("top", "P5 Omega") => 908,
        ("top", "P6 Alpha Omega") => 1100,
        ("fru", "P1 Fatebreaker") => 0,
        ("fru", "P2 Usurper of Frost") => 200,
        ("fru", "P3 Oracle of Darkness") => 500,
        ("fru", "P4 Enter the Dragon") => 680.8f,
        ("fru", "P5 Pandora") => 1029.6f,
        ("dmu", "P1 Kefka") => 0,
        ("dmu", "P2 Forsaken Kefka") => 207.6f,
        ("dmu", "P3 Chaos & Exdeath") => 497,
        ("dmu", "P4 Kefka Says") => 995,
        ("dmu", "P5 Kefka Reimagined") => 1255.6f,
        _ => null,
    };

    private static Dictionary<string, List<EncounterTimelineEvent>> Decode()
    {
        using var compressed = new MemoryStream(Convert.FromBase64String(EncodedData));
        using var gzip = new GZipStream(compressed, CompressionMode.Decompress);
        var encoded = JsonSerializer.Deserialize<Dictionary<string, List<EncodedEvent>>>(gzip) ?? [];
        return encoded.ToDictionary(
            pair => pair.Key,
            pair => pair.Value.Select((item, index) => new EncounterTimelineEvent
            {
                Id = $"cactbot-{pair.Key}-{index}",
                TimeSeconds = item.Time,
                SyncToSeconds = item.SyncTo,
                DurationSeconds = item.Duration,
                Name = item.Name,
                Phase = item.Phase,
                EventType = item.EventType,
                EventIds = item.EventIds ?? [],
                WindowBeforeSeconds = item.WindowBefore,
                WindowAfterSeconds = item.WindowAfter,
            }).ToList());
    }

    private sealed class EncodedEvent
    {
        [JsonPropertyName("t")] public float Time { get; set; }
        [JsonPropertyName("s")] public float SyncTo { get; set; }
        [JsonPropertyName("d")] public float Duration { get; set; }
        [JsonPropertyName("n")] public string Name { get; set; } = string.Empty;
        [JsonPropertyName("p")] public string Phase { get; set; } = string.Empty;
        [JsonPropertyName("e")] public TimelineSyncEventType? EventType { get; set; }
        [JsonPropertyName("i")] public List<uint>? EventIds { get; set; }
        [JsonPropertyName("b")] public float WindowBefore { get; set; }
        [JsonPropertyName("a")] public float WindowAfter { get; set; }
    }

    private const string EncodedData = "";
}
